import{dayKey,minuteOf,taskBounds,currentTask,initialSeconds,progress,segmentSeconds,remainingSeconds,validateTask}from'./core.mjs';
const $=id=>document.getElementById(id), esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), uid=()=>crypto.randomUUID(), KEY='ascend.v1';
const icons={calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M16 3v4M8 3v4M3 11h18M8 15h2m4 0h2"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',checklist:'<rect x="4" y="4" width="16" height="17" rx="2"/><path d="M8 2v4m8-4v4M8 13l3 3 5-6"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 0 1 5 .5c0 2-2.5 2-2.5 4M12 17h.01"/>',settings:'<path d="m10 3-.6 2.5-2 .9L5 5.7 3 9l1.8 1.8v2.4L3 15l2 3.3 2.4-.7 2 .9L10 21h4l.6-2.5 2-.9 2.4.7 2-3.3-1.8-1.8v-2.4L21 9l-2-3.3-2.4.7-2-.9L14 3z"/><circle cx="12" cy="12" r="3"/>',left:'<path d="m14 7-5 5 5 5"/>',right:'<path d="m10 7 5 5-5 5"/>',plus:'<path d="M12 5v14M5 12h14"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',play:'<path d="m9 5 11 7-11 7z"/>',pause:'<path d="M9 5v14M15 5v14"/>',volume:'<path d="m11 5-6 4H2v6h3l6 4zM15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.plus}</svg>`;
document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));
const emptyState=()=>({version:1,goals:[],tasks:[],sessions:[],history:{},selectedGoal:'',active:null,demo:false});
let state=emptyState(),storageError=false;
try{const saved=localStorage.getItem(KEY);if(saved){const parsed=JSON.parse(saved);if(validBackup(parsed))state={...emptyState(),...parsed};else storageError=true;}}catch{storageError=true;}
let selectedDate=dayKey(), prepared=null, detached=false, toastTimeout;
function validBackup(s){return s&&s.version===1&&Array.isArray(s.goals)&&Array.isArray(s.tasks)&&Array.isArray(s.sessions)&&s.goals.every(g=>typeof g.id==='string'&&typeof g.name==='string')&&s.tasks.every(t=>typeof t.id==='string'&&typeof t.title==='string'&&typeof t.date==='string'&&typeof t.start==='string'&&typeof t.end==='string'&&['task','commitment'].includes(t.kind)&&Number.isFinite(taskBounds(t).start)&&minuteOf(t.end)>minuteOf(t.start))&&s.sessions.every(v=>Number.isFinite(v.seconds)&&v.seconds>=0&&typeof v.date==='string')&&(!s.active||(typeof s.active.title==='string'&&Number.isFinite(s.active.remaining)&&Number.isFinite(s.active.elapsed)&&['running','paused','ended'].includes(s.active.status)&&Number.isFinite(s.active.endAt)));}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('Unable to save in this browser. Download a backup from Settings.');}}
function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('toast').hidden=true,4500);}
function goalName(id){return state.goals.find(g=>g.id===id)?.name||'General focus';}
function fmtTime(value){const[h,m]=value.split(':').map(Number);return`${h%12||12}${m?':'+String(m).padStart(2,'0'):''} ${h<12?'AM':'PM'}`;}
function niceDate(value,opts={month:'short',day:'numeric'}){return new Date(value+'T12:00:00').toLocaleDateString(undefined,opts);}
function options(selected,allText='No goal · general focus'){return`<option value="">${allText}</option>`+state.goals.map(g=>`<option value="${esc(g.id)}" ${g.id===selected?'selected':''}>${esc(g.name)}</option>`).join('');}
function snapshot(){const today=dayKey();state.history[today]=Object.fromEntries(['',...state.goals.map(g=>g.id)].map(id=>[id,progress(state.tasks,id).percent]));save();}
function render(){if(state.selectedGoal&&!state.goals.some(g=>g.id===state.selectedGoal))state.selectedGoal='';$('goalFilter').innerHTML=options(state.selectedGoal,'All goals');$('headerDate').textContent=niceDate(selectedDate,{weekday:'short',month:'long',day:'numeric'});$('todayButton').textContent=selectedDate===dayKey()?'Today':niceDate(selectedDate);$('demoBanner').hidden=!state.demo;renderTimeline();renderStats();renderFocus();}
function renderTimeline(){const tasks=state.tasks.filter(t=>t.date===selectedDate).sort((a,b)=>a.start.localeCompare(b.start));const startHour=Math.min(8,...tasks.map(t=>Math.floor(minuteOf(t.start)/60)));const endHour=Math.max(21,...tasks.map(t=>Math.ceil(minuteOf(t.end)/60)));const height=(endHour-startHour)*60;$('timeline').style.height=height+'px';let html='';for(let h=startHour;h<=endHour;h++)html+=`<span class="hour-label" style="top:${(h-startHour)*60}px">${h%12||12} ${h<12?'AM':'PM'}</span>`;
for(const t of tasks){const top=minuteOf(t.start)-startHour*60,duration=minuteOf(t.end)-minuteOf(t.start);html+=`<button class="task-block ${t.kind==='commitment'?'commitment':''} ${t.done?'done':''}" style="top:${top}px;height:${Math.max(duration-2,21)}px;left:3px;right:0" data-task="${esc(t.id)}" aria-label="${esc(t.title)}, ${fmtTime(t.start)} to ${fmtTime(t.end)}${t.done?', completed':''}">${duration>=35?`<span class="task-time">${fmtTime(t.start)} – ${fmtTime(t.end)}${t.done?' · ✓':''}</span>`:''}<span class="task-name">${esc(t.title)}</span>${duration>=75&&t.step?`<span class="task-step">${esc(t.step)}</span>`:''}${duration>=100&&t.goalId?`<span class="task-goal">${esc(goalName(t.goalId))}</span>`:''}</button>`;}
const now=new Date(),nowMin=now.getHours()*60+now.getMinutes();if(selectedDate===dayKey()&&nowMin>=startHour*60&&nowMin<=endHour*60)html+=`<div class="now-line" style="top:${nowMin-startHour*60}px"><span>NOW ${fmtTime(`${now.getHours()}:${String(now.getMinutes()).padStart(2,'0')}`)}</span></div>`;
if(!tasks.length)html+=`<div class="empty-day"><span class="empty-symbol">✳</span><h3>A little room to begin.</h3><p>Your day doesn't need to be full.<br>Start with one meaningful step.</p><button class="primary" id="emptyAddTask">Plan my first task</button>${!state.tasks.length?'<br><button class="text-button" id="emptySample">Or explore a sample day</button>':''}</div>`;$('timeline').innerHTML=html;$('timeline').querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>openTask(b.dataset.task));if($('emptyAddTask'))$('emptyAddTask').onclick=()=>openTask();if($('emptySample'))$('emptySample').onclick=loadSample;
const mins=tasks.reduce((s,t)=>s+minuteOf(t.end)-minuteOf(t.start),0);$('scheduleSummary').textContent=tasks.length?`${tasks.length} ${tasks.length===1?'item':'items'} · ${Math.floor(mins/60)}h ${mins%60?mins%60+'m ':''}planned`:'A fresh start, at your pace';$('dayCaption').textContent=niceDate(selectedDate,{weekday:'long'});}
function renderStats(){const id=state.selectedGoal,p=progress(state.tasks,id),sessions=state.sessions.filter(s=>!id||s.goalId===id);let seconds=sessions.reduce((a,s)=>a+s.seconds,0);if(state.active&&(!id||state.active.goalId===id))seconds+=state.active.elapsed+segmentSeconds(state.active);const hours=seconds/3600;$('hoursValue').innerHTML=`${hours===0?'0':hours<.1?'<0.1':hours.toFixed(1).replace(/\.0$/,'')}<span>h</span>`;$('hoursGoal').textContent=id?goalName(id):'your goals';$('sessionsCount').textContent=sessions.length?`${sessions.length} focus ${sessions.length===1?'session':'sessions'} logged`:'Your first session starts here';$('progressPercent').innerHTML=`${p.percent}<span>%</span>`;$('progressLabel').textContent=p.total?`${p.complete} of ${p.total} planned steps completed`:'No steps planned yet';$('progressDetail').textContent=id?goalName(id):'Across all your goals';
const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return{key:dayKey(d),label:d.toLocaleDateString(undefined,{weekday:'short'}).slice(0,1)};});const vals=days.map(d=>state.history[d.key]?.[id]??null);vals[6]=p.percent;let carry=null;const points=vals.map((v,i)=>{if(v!==null)carry=v;return carry===null?null:{x:i*40+4,y:66-carry*.58};});const known=points.filter(Boolean);const line=known.map((v,i)=>`${i?'L':'M'}${v.x},${v.y}`).join(' ');const area=known.length?`${line} L${known.at(-1).x},70 L${known[0].x},70Z`:'';$('chartWrap').innerHTML=`<svg viewBox="0 0 248 74" role="img" aria-label="Goal completion over the last seven days; today's progress is ${p.percent} percent"><defs><linearGradient id="chartFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#df8dbb" stop-opacity=".2"/><stop offset="100%" stop-color="#df8dbb" stop-opacity=".02"/></linearGradient></defs><path d="M4 8H244 M4 37H244 M4 66H244" stroke="#f3eef1" stroke-width="1"/><path d="${area}" fill="url(#chartFill)"/><path d="${line}" fill="none" stroke="#cf5597" stroke-width="1.8"/>${known.map(v=>`<circle cx="${v.x}" cy="${v.y}" r="2.5" fill="white" stroke="#cf5597" stroke-width="1.4"/>`).join('')}</svg><div class="chart-labels">${days.map(d=>`<span>${d.label}</span>`).join('')}</div>`;}
function selection(){if(state.active)return state.active;if(prepared)return prepared;if(!detached){const t=currentTask(state.tasks);if(t)return{taskId:t.id,goalId:t.goalId,title:t.title,step:t.step,remaining:initialSeconds(t),total:initialSeconds(t),scheduled:true};}return null;}
function renderFocus(){const s=selection(),active=state.active;const secs=s?(active?remainingSeconds(active):s.remaining):1500;$('focusHeading').textContent=s?s.title:'Start a new session';$('focusContext').textContent=s?(s.step||(s.goalId?goalName(s.goalId):s.taskId?'Your scheduled task':'Independent focus')):'One thing at a time.';$('timer').textContent=`${String(Math.floor(secs/60)).padStart(2,'0')}:${String(secs%60).padStart(2,'0')}`;$('timerCaption').textContent=active?(active.status==='running'?'A LITTLE MOMENTUM':active.status==='ended'?'A MOMENT TO REFLECT':'TAKE YOUR TIME'):s?.taskId?'READY WHEN YOU ARE':'MINUTES OF POSSIBILITY';$('timerRing').classList.toggle('running',active?.status==='running');$('timerRing').classList.toggle('paused',active?.status==='paused');
$('timerActions').innerHTML=active?(active.status==='ended'?'<button class="primary" id="checkIn">Check in</button>':`<button class="primary" id="pauseTimer">${active.status==='running'?'Pause':'Resume'}</button><button class="secondary" id="finishTimer">Finish</button>`):'<button class="primary" id="startTimer">Start session</button>';
$('focusSecondary').innerHTML=active?'':`<button id="independentButton">Independent session</button>${detached||prepared?'<button id="followSchedule">Follow schedule</button>':''}`;if($('startTimer'))$('startTimer').onclick=startTimer;if($('pauseTimer'))$('pauseTimer').onclick=togglePause;if($('finishTimer'))$('finishTimer').onclick=()=>endCheckIn();if($('checkIn'))$('checkIn').onclick=()=>showFinish();if($('independentButton'))$('independentButton').onclick=openIndependent;if($('followSchedule'))$('followSchedule').onclick=()=>{prepared=null;detached=false;renderFocus();};}
function startTimer(){let s=selection();if(!s){openIndependent();return;}const now=Date.now();state.active={...s,id:uid(),date:dayKey(),remaining:s.remaining,total:s.remaining,elapsed:0,status:'running',runningSince:now,endAt:now+s.remaining*1000};prepared=null;save();renderFocus();}
function accrue(){const s=state.active;if(!s||s.status!=='running')return;s.elapsed+=segmentSeconds(s);s.remaining=remainingSeconds(s);s.runningSince=null;}
function togglePause(){const s=state.active;if(!s)return;if(s.status==='running'){accrue();s.status='paused';}else{const now=Date.now();s.status='running';s.runningSince=now;s.endAt=now+s.remaining*1000;}save();renderFocus();}
function endCheckIn(){if(!state.active)return;accrue();state.active.status='ended';save();renderFocus();showFinish();}
function showFinish(){const s=state.active;if(!s)return;$('finishMessage').textContent=`You spent ${Math.max(0,Math.round(s.elapsed/60))} ${Math.round(s.elapsed/60)===1?'minute':'minutes'} on “${s.title}”. ${s.taskId?'How did it go?':'Every bit of focus counts.'}`;$('markComplete').hidden=!s.taskId;$('saveProgress').textContent=s.taskId?'Save session · more to do':'Save session';if(!$('finishDialog').open)$('finishDialog').showModal();}
function logSession(complete=false){const s=state.active;if(!s)return;accrue();if(s.elapsed>0)state.sessions.push({id:s.id,taskId:s.taskId||null,goalId:s.goalId||'',title:s.title,date:s.date,seconds:Math.round(s.elapsed),endedAt:Date.now()});if(complete){const task=state.tasks.find(t=>t.id===s.taskId);if(task){task.done=true;task.completedAt=Date.now();}}state.active=null;prepared=null;detached=false;snapshot();$('finishDialog').close();render();toast(complete?'One more step forward. Task completed.':'Your focus time is saved.');}
function openTask(id){const task=state.tasks.find(t=>t.id===id);$('taskForm').reset();$('taskError').textContent='';$('taskId').value=task?.id||'';$('taskDialogTitle').textContent=task?'Edit scheduled task':'Plan a task';$('taskTitle').value=task?.title||'';$('taskKind').value=task?.kind||'task';$('completionLabel').hidden=!task||task.kind!=='task';$('taskDone').checked=task?.done||false;$('taskGoal').innerHTML=options(task?.goalId??state.selectedGoal);$('taskStep').value=task?.step||'';$('taskDate').value=task?.date||selectedDate;const now=new Date();const h=Math.min(22,now.getHours()+1);$('taskStart').value=task?.start||`${String(h).padStart(2,'0')}:00`;$('taskEnd').value=task?.end||`${String(h).padStart(2,'0')}:30`;$('deleteTask').hidden=!task;$('focusTask').hidden=!task||task.kind!=='task'||task.done;$('taskGoal').disabled=$('taskKind').value==='commitment';$('taskDialog').showModal();}
$('taskKind').onchange=()=>{$('taskGoal').disabled=$('taskKind').value==='commitment';$('completionLabel').hidden=!$('taskId').value||$('taskKind').value!=='task';};
$('taskForm').onsubmit=e=>{e.preventDefault();const id=$('taskId').value;const prior=state.tasks.find(t=>t.id===id);if(state.active?.taskId===id){$('taskError').textContent='Finish the active focus session before editing this task.';return;}const task={...prior,id:id||uid(),title:$('taskTitle').value.trim(),kind:$('taskKind').value,goalId:$('taskKind').value==='commitment'?'':$('taskGoal').value,step:$('taskStep').value.trim(),date:$('taskDate').value,start:$('taskStart').value,end:$('taskEnd').value,done:$('taskKind').value==='task'&&$('taskDone').checked};const error=validateTask(task,state.tasks);if(error){$('taskError').textContent=error;return;}if(prior)state.tasks=state.tasks.map(t=>t.id===id?task:t);else state.tasks.push(task);if(prepared?.taskId===id)prepared=null;selectedDate=task.date;snapshot();$('taskDialog').close();render();toast(prior?'Your schedule is updated.':'A little structure added to your day.');};
$('deleteTask').onclick=()=>{const id=$('taskId').value;if(state.active?.taskId===id){$('taskError').textContent='Finish the active focus session before deleting this task.';return;}if(!confirm('Delete this task? Logged focus time will be kept.'))return;state.tasks=state.tasks.filter(t=>t.id!==id);if(prepared?.taskId===id)prepared=null;snapshot();$('taskDialog').close();render();toast('Task removed.');};
$('focusTask').onclick=()=>{if(state.active){$('taskError').textContent='Finish your current focus session before switching tasks.';return;}const t=state.tasks.find(t=>t.id===$('taskId').value);prepared={taskId:t.id,goalId:t.goalId,title:t.title,step:t.step,remaining:initialSeconds(t),scheduled:true};detached=false;$('taskDialog').close();renderFocus();document.querySelector('.focus-card').scrollIntoView({behavior:'smooth',block:'center'});};
function openGoals(){$('goalsList').innerHTML=state.goals.length?state.goals.map(g=>{const p=progress(state.tasks,g.id);return`<div class="goal-row ${state.selectedGoal===g.id?'selected':''}"><div><strong>${esc(g.name)}</strong><p>${p.complete} of ${p.total} planned steps completed</p></div><button data-select-goal="${esc(g.id)}">${state.selectedGoal===g.id?'Selected':'Select'}</button></div>`;}).join(''):'<p class="dialog-description">Your first goal starts here.</p>';$('goalsList').querySelectorAll('[data-select-goal]').forEach(b=>b.onclick=()=>{state.selectedGoal=b.dataset.selectGoal;save();render();$('goalsDialog').close();});if(!$('goalsDialog').open)$('goalsDialog').showModal();}
$('goalForm').onsubmit=e=>{e.preventDefault();const name=$('goalName').value.trim();if(!name)return;if(state.goals.some(g=>g.name.toLowerCase()===name.toLowerCase())){toast('That goal already exists.');return;}const g={id:uid(),name,createdAt:Date.now()};state.goals.push(g);state.selectedGoal=g.id;$('goalForm').reset();snapshot();render();openGoals();toast('Your goal has a place. Now add a small next step.');};
$('goalFilter').onchange=e=>{state.selectedGoal=e.target.value;save();renderStats();};
function openIndependent(){if(state.active){toast('Finish your current session first.');return;}$('independentTitle').value='';$('independentGoal').innerHTML=options(state.selectedGoal);$('independentDialog').showModal();}
$('independentForm').onsubmit=e=>{e.preventDefault();const mins=Number($('independentMinutes').value),title=$('independentTitle').value.trim();if(!title||mins<1||mins>240)return;prepared={taskId:null,goalId:$('independentGoal').value,title,remaining:mins*60};detached=true;$('independentDialog').close();renderFocus();toast('Your independent session is ready.');};
$('markComplete').onclick=()=>logSession(true);$('saveProgress').onclick=()=>logSession(false);$('extendSession').onclick=()=>{const s=state.active;if(!s)return;const now=Date.now();s.remaining=300;s.total+=300;s.runningSince=now;s.endAt=now+300000;s.status='running';save();$('finishDialog').close();renderFocus();};
$('finishDialog').addEventListener('cancel',e=>{e.preventDefault();$('finishDialog').close();});
function moveDay(delta){const d=new Date(selectedDate+'T12:00:00');d.setDate(d.getDate()+delta);selectedDate=dayKey(d);render();}
$('prevDay').onclick=()=>moveDay(-1);$('nextDay').onclick=()=>moveDay(1);$('todayButton').onclick=$('todayNav').onclick=()=>{selectedDate=dayKey();render();};$('addTask').onclick=$('planningNav').onclick=()=>openTask();$('addGoal').onclick=$('goalsNav').onclick=openGoals;$('settingsNav').onclick=()=>$('settingsDialog').showModal();$('helpNav').onclick=()=>$('helpDialog').showModal();document.querySelector('.wordmark').onclick=e=>{e.preventDefault();selectedDate=dayKey();render();};document.querySelectorAll('.close-dialog').forEach(b=>b.onclick=()=>b.closest('dialog').close());
function loadSample(){if(state.active){toast('Finish your focus session first.');return;}if(state.tasks.length||state.goals.length){toast('A sample day is available in an empty workspace. Export your data before resetting.');return;}const today=dayKey(),g1={id:uid(),name:'Build my design career'},g2={id:uid(),name:'Make time for myself'};state.goals=[g1,g2];state.selectedGoal=g1.id;state.demo=true;const samples=[['09:00','09:30','Set the day in motion','Pick three things that matter today','task',g1.id,true],['10:00','12:00','Job search','Find three roles and tailor one application','task',g1.id,false],['12:30','13:30','Lunch & a little fresh air','','commitment','',false],['14:00','15:00','Explore portfolio ideas','Sketch three directions for a case study','task',g1.id,false],['17:30','18:30','Workout · push day','Show up. Start with the warm-up.','task',g2.id,false]];state.tasks=samples.map(([start,end,title,step,kind,goalId,done])=>({id:uid(),date:today,start,end,title,step,kind,goalId,done}));state.sessions=[{id:uid(),date:today,title:'Set the day in motion',goalId:g1.id,seconds:1500}];snapshot();selectedDate=today;$('settingsDialog').close();render();toast('Sample day loaded. All of this data is just for exploring.');}
$('sampleDay').onclick=loadSample;$('clearDemo').onclick=()=>{if(confirm('Remove the sample day and start fresh? Any changes made to the sample will be removed.'))reset();};
function reset(){state=emptyState();prepared=null;detached=false;selectedDate=dayKey();save();document.querySelectorAll('dialog[open]').forEach(d=>d.close());render();toast('A fresh start.');}
$('resetData').onclick=()=>{if(confirm('Delete all goals, tasks, and focus history in this browser? Download a backup first if you want to keep them.'))reset();};
$('exportData').onclick=()=>{const copy=structuredClone(state);if(copy.active){copy.active.elapsed+=segmentSeconds(copy.active);copy.active.remaining=remainingSeconds(copy.active);copy.active.runningSince=null;copy.active.status='paused';}const blob=new Blob([JSON.stringify(copy,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`ascend-backup-${dayKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup downloaded.');};
$('importData').onclick=()=>$('importFile').click();$('importFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>5000000)throw Error();const data=JSON.parse(await f.text());if(!validBackup(data))throw Error();if(!confirm('Replace this browser’s data with the backup?'))return;state={...emptyState(),...data};state.history=state.history&&typeof state.history==='object'?state.history:{};prepared=null;detached=false;save();render();$('settingsDialog').close();toast('Backup restored.');}catch{toast('This file is not a valid Ascend backup.');}finally{e.target.value='';}};
let audioContext=null,audioSource=null,audioGain=null,audioFilter=null,lfo=null,lfoGain=null,audioPlaying=false;
async function playSound(){try{if(!audioContext)audioContext=new(window.AudioContext||window.webkitAudioContext)();await audioContext.resume();if(audioSource){audioSource.stop();audioSource.disconnect();}if(lfo){lfo.stop();lfo.disconnect();lfo=null;}if(audioGain)audioGain.disconnect();if(audioFilter)audioFilter.disconnect();if(lfoGain)lfoGain.disconnect();const type=$('soundType').value,rate=audioContext.sampleRate,buffer=audioContext.createBuffer(1,rate*8,rate),data=buffer.getChannelData(0);let last=0;for(let i=0;i<data.length;i++){const white=Math.random()*2-1;if(type==='rain')data[i]=white*.35;else{last=(last+.02*white)/1.02;data[i]=last*3.5;}}audioSource=audioContext.createBufferSource();audioSource.buffer=buffer;audioSource.loop=true;audioFilter=audioContext.createBiquadFilter();audioFilter.type='lowpass';audioFilter.frequency.value=type==='rain'?2800:type==='ocean'?700:450;audioGain=audioContext.createGain();audioGain.gain.value=Number($('volume').value)/100*.6;audioSource.connect(audioFilter).connect(audioGain).connect(audioContext.destination);if(type==='ocean'){lfo=audioContext.createOscillator();lfo.frequency.value=.12;lfoGain=audioContext.createGain();lfoGain.gain.value=Number($('volume').value)/100*.25;lfo.connect(lfoGain).connect(audioGain.gain);lfo.start();}audioSource.start();audioPlaying=true;renderMusic();}catch{toast('Audio could not start. Try again in a supported browser.');}}
function renderMusic(){$('musicPlay').innerHTML=icon(audioPlaying?'pause':'play');$('musicPlay').setAttribute('aria-label',audioPlaying?'Pause ambient sound':'Play ambient sound');$('soundStatus').textContent=audioPlaying?'PLAYING':'OFF';$('albumArt').classList.toggle('playing',audioPlaying);}
$('musicPlay').onclick=()=>{if(audioPlaying){audioContext.suspend();audioPlaying=false;renderMusic();}else playSound();};$('soundType').onchange=()=>{if(audioPlaying)playSound();};$('volume').oninput=e=>{const v=Number(e.target.value)/100;if(audioGain)audioGain.gain.setTargetAtTime(v*.6,audioContext.currentTime,.1);if(lfoGain)lfoGain.gain.setTargetAtTime(v*.25,audioContext.currentTime,.1);};
let lastMinute='',lastTaskId='',lastDay=dayKey();function tick(){const now=new Date(),minute=now.toISOString().slice(0,16);if(lastMinute!==minute){if(lastDay!==dayKey()){if(selectedDate===lastDay)selectedDate=dayKey();lastDay=dayKey();}lastMinute=minute;renderTimeline();renderStats();}if(state.active?.status==='running'){if(remainingSeconds(state.active)===0){endCheckIn();}else{const seconds=remainingSeconds(state.active);$('timer').textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;}}else if(!state.active&&!prepared&&!detached){const current=currentTask(state.tasks);if(current?.id!==lastTaskId){lastTaskId=current?.id;renderFocus();}else if(current){const s=initialSeconds(current);$('timer').textContent=`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}}}
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{const incoming=JSON.parse(e.newValue);if(validBackup(incoming)){state={...emptyState(),...incoming};render();toast('Updated from another Ascend tab.');}}catch{}}});document.addEventListener('visibilitychange',()=>{if(!document.hidden){tick();renderFocus();}});
const quotes=[['A reminder for you,','You are<br>doing<br><em>great!</em>'],['At your own pace,','Little by<br><em>little.</em>'],['Keep showing up,','Progress,<br>not<br><em>perfection.</em>']];const q=quotes[new Date().getDate()%quotes.length];$('quoteIntro').textContent=q[0];$('quote').innerHTML=q[1];render();if(state.active?.status==='ended')showFinish();tick();setInterval(tick,1000);if(storageError)toast('Saved data could not be read. Your previous storage has not been overwritten.');
